from urllib.parse import urlparse

from django import forms

from .models import HelpLink


class HelpLinkForm(forms.ModelForm):
    class Meta:
        model = HelpLink
        fields = '__all__'

    def clean_url_source(self):
        """Transforma o valor no formato admin/{app}/{model}/"""
        value = self.cleaned_data.get('url_source')

        if not value:
            return value

        parsed = urlparse(value)
        # usa apenas o path (ignora domínio, query, fragment)
        path = parsed.path or ''
        parts = path.strip('/').split('/')
        # tenta encontrar o padrão começando por "admin"
        try:
            admin_index = parts.index('admin')
            parts = parts[admin_index:]
        except ValueError:
            raise forms.ValidationError('Não foi possível identificar o padrão /admin/{app}/{model}/.')
        # precisa ter pelo menos admin/app/model
        if len(parts) < 3 or parts[0] != 'admin':
            raise forms.ValidationError('A URL deve estar no formato /admin/{app}/{model}/.')

        app_label = parts[1]
        model_name = parts[2]

        if not app_label or not model_name:
            raise forms.ValidationError('App e model inválidos.')
        # reconstrói no formato canônico
        normalized_path = f'/admin/{app_label}/{model_name}/'

        return normalized_path
